\fill[black] (3,0) circle (1.5pt);
\fill[black] (6,0) circle (1.5pt);
\draw[black] (1.5,-0.10)--(1.5,0.10);
\draw[black] (4.5,-0.10)--(4.5,0.10);
\path (0,0) node[below=5pt] {$C$};
\path (3,0) node[below=5pt] {$N$};
